 double low=slider.minValue;next=a.navigatorFormulaSettings;formula_slot_set_value(&next.program.slots[0],0,low);a.navigatorFormulaSettings=next;slider.doubleValue=slider.trackingValue=low;slider.finished();assert(slider.doubleValue==low&&slider.minValue==low-1.5&&slider.maxValue==low+1.5);
